index 0000000..d9e74e7
--- /dev/null
+++ b/src/session-token.ts
@@ -0,0 +1,48 @@
+import { createHmac, randomBytes } from "crypto";
+
+const SIGNING_KEY = process.env.SESSION_SIGNING_KEY || "";
+const TOKEN_TTL_SECONDS = 60;
+
+export interface TokenPayload {
+  sessionId: string;
+  userId: string;
+  issuedAt: number;
+  expiresAt: number;
+}
+
+export const issueSessionToken = (
+  sessionId: string,
+  userId: string,
+): string => {
+  const issuedAt = Math.floor(Date.now() / 1000);
+  const expiresAt = issuedAt + TOKEN_TTL_SECONDS;
+
+  const payload = { sessionId, userId, issuedAt, expiresAt };
+  const nonce = randomBytes(16).toString("hex");
+  const message = `${nonce}:${JSON.stringify(payload)}`;
+  const signature = createHmac("sha256", SIGNING_KEY).update(message).digest("hex");
+
+  return `${nonce}.${Buffer.from(JSON.stringify(payload)).toString("base64")}.${signature}`;
+};
+
+export const verifySessionToken = (token: string): TokenPayload | null => {
+  try {
+    const parts = token.split(".");
+    if (parts.length !== 3) return null;
+
+    const [nonce, payloadB64, signature] = parts;
+    const payload = JSON.parse(Buffer.from(payloadB64, "base64").toString());
+
+    const message = `${nonce}:${JSON.stringify(payload)}`;
+    const expectedSignature = createHmac("sha256", SIGNING_KEY).update(message).digest("hex");
+
+    if (signature !== expectedSignature) return null;
+
+    const now = Math.floor(Date.now() / 1000);
+    if (payload.expiresAt < now) return null;
+
+    return payload as TokenPayload;
+  } catch {
+    return null;
+  }
+};
